  WITH CHECK (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_checklists.submission_id
       AND ts.submitted_by = (SELECT auth.uid())
       AND ts.status = 'uploading'
       AND true
  ));


